export function generateCartItemsHtml(items, currencySymbol = '£') {
  if (!items || items.length === 0) {
    return '<div style="background-color:#ffffff; border-radius:8px; border:1px solid #e4dff0; padding:20px; text-align:center; color:#666; font-family:Arial,sans-serif; font-size:14px;">Your selected biological oral care items</div>';
  }

  return items.map(item => {
    const cleanTitle = (item.title || 'Biological Oral Care')
      .replace(/[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F600}-\u{1F64F}\u{1F680}-\u{1F6FF}]/gu, '')
      .trim();

    const variantHtml = (item.variantTitle && item.variantTitle !== 'Default Title' && item.variantTitle !== 'null')
      ? '<p style="color:#2D8B7A; font-size:11px; letter-spacing:1px; text-transform:uppercase; margin:0 0 8px 0; font-family:Arial,sans-serif; font-weight:bold;">' + item.variantTitle + '</p>'
      : '';

    const imgHtml = '<table cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto; background-color:#ffffff; border-radius:6px; border:1px solid #eae5f4;"><tr><td width="88" height="88" align="center" valign="middle" style="width:88px; height:88px; text-align:center; vertical-align:middle; padding:3px; background-color:#ffffff; border-radius:6px;"><img src="' + (item.image || '') + '" alt="' + cleanTitle + '" width="82" height="82" style="display:block; margin:0 auto; max-width:82px; max-height:82px; width:auto; height:auto; border-radius:4px;" /></td></tr></table>';

    const itemPrice = parseFloat(item.price || 0);
    const priceDisplay = itemPrice > 0 ? (currencySymbol + itemPrice.toFixed(2)) : 'Complimentary';

    return '<div style="background-color:#ffffff; border-radius:8px; border:1px solid #e4dff0; margin-bottom:12px; overflow:hidden; box-shadow:0 2px 8px rgba(74,48,96,0.06);">' +
      '<table width="100%" cellpadding="0" cellspacing="0" border="0"><tr>' +
      '<td width="115" style="padding:10px 8px; vertical-align:middle; text-align:center; background:linear-gradient(135deg, #f5f2fc, #eef9f7); border-right:1px solid #e4dff0;">' + imgHtml + '</td>' +
      '<td style="padding:18px 20px; vertical-align:middle; text-align:left;">' +
      '<p style="color:#4A3060; font-size:16px; font-weight:normal; margin:0 0 4px 0; font-style:italic; line-height:1.3; font-family:Georgia,serif;">' + cleanTitle + '</p>' +
      variantHtml +
      '<p style="color:#888888; font-size:12px; margin:0 0 8px 0; font-family:Arial,sans-serif;">Quantity: ' + (item.quantity || 1) + '</p>' +
      '<p style="color:#4A3060; font-size:17px; font-weight:bold; margin:0; font-family:Arial,sans-serif;">' + priceDisplay + '</p>' +
      '</td></tr></table></div>';
  }).join('');
}

export function renderTemplate(templateId, checkout, customSubject = null) {
  const config = TEMPLATE_CONFIGS.find(t => t.id === Number(templateId)) || {
    id: templateId,
    subject: 'Did you leave something behind?'
  };

  const rawHtml = TEMPLATES[Number(templateId)] || TEMPLATES[1];
  const firstName = (checkout.firstName || checkout.first_name || 'Valued Customer').trim();
  const lastName = (checkout.lastName || checkout.last_name || '').trim();
  const email = checkout.email || '';
  const currencySymbol = checkout.currencySymbol || (checkout.currency === 'USD' ? '$' : '£');
  const totalPrice = checkout.totalPrice || checkout.total_price || '0.00';
  const cartItemsHtml = generateCartItemsHtml(checkout.items || [], currencySymbol);

  let recoveryUrl = checkout.abandonedCheckoutUrl || checkout.abandoned_checkout_url || 'https://shop.thedentalshaman.com';

  const discountCode = Number(templateId) >= 3 ? 'Marc11' : '';

  let html = rawHtml
    .replace(/\{\{\s*first_name\s*\}\}/gi, firstName)
    .replace(/\{\{\s*customer_name\s*\}\}/gi, checkout.fullName || firstName)
    .replace(/\{\{\s*email\s*\}\}/gi, email)
    .replace(/\{\{\s*cart_items\s*\}\}/gi, cartItemsHtml)
    .replace(/\{\{\s*currency_symbol\s*\}\}/gi, currencySymbol)
    .replace(/\{\{\s*total_price\s*\}\}/gi, parseFloat(totalPrice).toFixed(2))
    .replace(/\{\{\s*recovery_url\s*\}\}/gi, recoveryUrl)
    .replace(/\{\{\s*discount_code\s*\}\}/gi, discountCode)
    .replace(/\{\{\s*app_url\s*\}\}/gi, 'https://shop.thedentalshaman.com');

  let subject = customSubject || config.subject;
  subject = subject
    .replace(/\{\{\s*first_name\s*\}\}/gi, firstName)
    .replace(/\{\{\s*customer_name\s*\}\}/gi, checkout.fullName || firstName)
    .replace(/\{\{\s*discount_code\s*\}\}/gi, discountCode);

  return { html, subject };
}
